import { test, expect } from '@playwright/test';
import { BRANCH, SERVICE, USER, addDays, apiCall, businessDate, chooseBranchAndService, openAs, resetStore } from './support';

test.beforeEach(async ({ request }) => {
  await resetStore(request);
});

async function openAppointmentForm(page: import('@playwright/test').Page, date: string, serviceId: string) {
  await page.goto('/customer');
  await chooseBranchAndService(page, BRANCH.downtown, serviceId);
  await page.getByTestId('book-mode-appointment').check();
  await page.getByTestId('book-date').fill(date);
}

test('TR-5: Appointment Conflict Prevention', async ({ page, request }) => {
  const tomorrow = addDays(await businessDate(request), 1);

  await openAs(page, USER.alex, '/customer');
  await openAppointmentForm(page, tomorrow, SERVICE.general);
  const firstAvailable = page.locator('[data-testid=slot][data-available="true"]').first();
  await expect(firstAvailable).toBeVisible();
  const startTime = (await firstAvailable.getAttribute('data-id')) ?? '';
  expect(startTime).toMatch(/^\d{2}:\d{2}$/);
  await firstAvailable.click();

  const [booked] = await Promise.all([
    page.waitForResponse((r) => new URL(r.url()).pathname === '/api/appointments' && r.request().method() === 'POST'),
    page.getByTestId('book-submit').click(),
  ]);
  expect(booked.status()).toBe(201);
  await expect(page.getByTestId('appointment-result')).toBeVisible();
  await expect(page.getByTestId('appointment-time')).toContainText(startTime);

  const sameSlotSameService = await apiCall(request, USER.emma, 'POST', '/api/appointments', {
    branchId: BRANCH.downtown,
    serviceId: SERVICE.general,
    date: tomorrow,
    startTime,
  });
  expect(sameSlotSameService.status).toBe(409);
  expect(sameSlotSameService.body.error.code).toBe('SLOT_UNAVAILABLE');

  const sameSlotOtherService = await apiCall(request, USER.james, 'POST', '/api/appointments', {
    branchId: BRANCH.downtown,
    serviceId: SERVICE.support,
    date: tomorrow,
    startTime,
  });
  expect(sameSlotOtherService.status).toBe(409);
  expect(sameSlotOtherService.body.error.code).toBe('SLOT_UNAVAILABLE');

  const emmaPage = await page.context().browser()!.newContext({ baseURL: page.url().split('/customer')[0] });
  const emma = await emmaPage.newPage();
  await openAs(emma, USER.emma, '/customer');
  await openAppointmentForm(emma, tomorrow, SERVICE.general);
  const blockedSlot = emma.locator(`[data-testid=slot][data-id="${startTime}"]`);
  await expect(blockedSlot).toHaveAttribute('data-available', 'false');
  await expect(blockedSlot).toBeDisabled();
  await expect(blockedSlot).toContainText('Unavailable');
  await emmaPage.close();

  const mine = await apiCall(request, USER.alex, 'GET', '/api/appointments/mine');
  const sameStart = (mine.body as any[]).filter((appointment) => appointment.date === tomorrow && appointment.startTime === startTime && appointment.status === 'scheduled');
  expect(sameStart).toHaveLength(1);
});

test('TR-5: seeded counter conflict is blocked in the booking form', async ({ page }) => {
  await openAs(page, USER.emma, '/customer');
  await openAppointmentForm(page, (await page.getByTestId('book-date').inputValue()) || '', SERVICE.general);
  const seededSlot = page.locator('[data-testid=slot][data-id="15:00"]');
  await expect(seededSlot).toHaveAttribute('data-available', 'false');
  await expect(seededSlot).toBeDisabled();
});

